<span class="line"><span style="color:#C678DD;">    for</span><span style="color:#ABB2BF;"> X, y </span><span style="color:#C678DD;">in</span><span style="color:#61AFEF;"> data_iter</span><span style="color:#ABB2BF;">(batch_size, features, labels):</span></span>
