<span class="line"><span style="color:#ABB2BF;">        l </span><span style="color:#56B6C2;">=</span><span style="color:#61AFEF;"> loss</span><span style="color:#ABB2BF;">(</span><span style="color:#61AFEF;">net</span><span style="color:#ABB2BF;">(X, w, b), y)  </span><span style="color:#7F848E;font-style:italic;"># X和y的小批量损失</span></span>
